//! `vectors/plugins/commands/lists.json`, generated by
//! `suites/command-lists.ts`: each owner's command list (#1091, #1089)
//! through the commands plugin, next to its owner and without it.

use std::any::Any;
use std::rc::Rc;

use epdf_kernel::rt::Promise;
use epdf_kernel::{AnyPlugin, AnyToken, Error, undefined};
use epdf_plugin_annotation::harness::Annotation;
use epdf_plugin_commands::harness::{CommandLists, functions};
use epdf_plugin_commands::{CommandItem, DocumentCommandsPlatform, create_document_commands};
use epdf_plugin_history::harness::History;
use epdf_plugin_i18n::harness::I18n;
use epdf_plugin_interaction::harness::Interaction;
use epdf_plugin_render::PageImage;
use epdf_plugin_render::commands::RenderCommandsPlatform;
use epdf_plugin_render::harness::Render;
use epdf_plugin_selection::SelectionCapability;
use epdf_plugin_selection::commands::SelectionCommandsPlatform;
use epdf_plugin_selection::harness::Selection;
use plugin_conformance::{Harness, HarnessPlugin, Outcome, Registry, assert_suite};
use serde_json::{Value, json};

/// The host's part of the lists: each call logged, as the generator's
/// platform logs it.
struct Logged(Harness);

impl DocumentCommandsPlatform for Logged {
    fn save_file(&self, _bytes: Value, file_name: String, content_type: String) {
        self.0.log("saveFile", vec![json!(file_name), json!(content_type)]);
    }
}

impl SelectionCommandsPlatform for Logged {
    fn copy_selection(&self, _selection: &SelectionCapability) -> Promise<Value> {
        self.0.log("copySelection", Vec::new());
        Promise::resolved(undefined())
    }
}

impl RenderCommandsPlatform for Logged {
    fn copy_image(&self, _image: Promise<PageImage>) -> Promise<Value> {
        self.0.log("copyImage", Vec::new());
        Promise::resolved(undefined())
    }

    /// The generator's picture has a `blob()` that answers at once, unlogged.
    fn image_bytes(&self, _image: PageImage) -> Promise<Value> {
        Promise::resolved(Value::Null)
    }

    fn save_file(&self, _bytes: Value, file_name: String, content_type: String) {
        self.0.log("saveFile", vec![json!(file_name), json!(content_type)]);
    }
}

/// `snapshot-render`: the render plugin as the generator builds it there,
/// whose picture also has a `blob()` (the Rust side's `image_bytes`).
struct SnapshotRender;

impl HarnessPlugin for SnapshotRender {
    fn factories(&self) -> Vec<&'static str> {
        vec!["snapshot-render"]
    }

    fn build(&self, _factory: &str, config: &Value, h: &Harness) -> Result<AnyPlugin, Error> {
        Render.build("render", config, h)
    }

    fn tokens(&self) -> Vec<AnyToken> {
        Render.tokens()
    }

    fn call(
        &self,
        capability: &Rc<dyn Any>,
        method: &str,
        args: Vec<Value>,
        h: &Harness,
    ) -> Option<Outcome> {
        Render.call(capability, method, args, h)
    }

    fn members(&self, capability: &Rc<dyn Any>) -> Option<Vec<&'static str>> {
        Render.members(capability)
    }
}

fn items<D: Into<CommandItem>>(list: Vec<D>) -> Vec<CommandItem> {
    list.into_iter().map(Into::into).collect()
}

fn list(name: &str, h: &Harness) -> Option<Vec<CommandItem>> {
    let platform = Rc::new(Logged(h.clone()));
    Some(match name {
        "document" => items(create_document_commands(platform)),
        "history" => items(epdf_plugin_history::commands::create_history_commands()),
        "interaction" => epdf_plugin_interaction::commands::create_interaction_commands(),
        "selection" => items(epdf_plugin_selection::commands::create_selection_commands(platform)),
        "annotation" => items(epdf_plugin_annotation::commands::create_annotation_commands()),
        "render" => items(epdf_plugin_render::commands::create_render_commands(platform)),
        "stage" => items(epdf_plugin_stage::commands::create_stage_commands()),
        _ => return None,
    })
}

#[test]
fn the_command_lists_match_the_typescript() {
    let registry = Registry::new()
        .with(CommandLists(Rc::new(list)))
        .with(History)
        .with(I18n)
        .with(Interaction)
        .with(Selection)
        .with(SnapshotRender)
        .with(Annotation);
    assert_suite("plugins/commands/lists.json", &registry, &functions());
}

/// The render platform whose `image_bytes` rejects: a picture that can't be
/// encoded, as a `blob()` that rejects upstream.
struct Unencodable(Harness);

impl RenderCommandsPlatform for Unencodable {
    fn copy_image(&self, _image: Promise<PageImage>) -> Promise<Value> {
        Promise::resolved(undefined())
    }

    fn image_bytes(&self, _image: PageImage) -> Promise<Value> {
        Promise::rejected(Error::new("the picture could not be encoded"))
    }

    fn save_file(&self, _bytes: Value, file_name: String, content_type: String) {
        self.0.log("saveFile", vec![json!(file_name), json!(content_type)]);
    }
}

/// `snapshot:save` with a picture `image_bytes` refuses: the command
/// rejects and `save_file` is never called (CU-C5-D4). Rust only, since
/// upstream's generator has no `blob()` that rejects; the steps are the
/// `snapshot-commands` case's.
#[test]
fn a_picture_that_cannot_be_encoded_fails_snapshot_save_before_anything_is_saved() {
    let suite = plugin_conformance::load("plugins/commands/lists.json");
    let case = suite["cases"]
        .as_array()
        .and_then(|cases| cases.iter().find(|case| case["name"] == "snapshot-commands"))
        .expect("the snapshot-commands case")
        .clone();
    let registry = Registry::new()
        .with(CommandLists(Rc::new(|name: &str, h: &Harness| {
            (name == "render").then(|| {
                items(epdf_plugin_render::commands::create_render_commands(Rc::new(Unencodable(
                    h.clone(),
                ))))
            })
        })))
        .with(Interaction)
        .with(SnapshotRender);
    let run = plugin_conformance::scenario::run_case(&case, &registry);

    let callbacks: Vec<&Value> = run
        .trace
        .iter()
        .flat_map(|entry| entry["callbacks"].as_array().into_iter().flatten())
        .collect();
    assert!(callbacks.iter().all(|call| call["fn"] != "saveFile"), "{callbacks:?}");
    // Step 7 executes `snapshot:save`; the settle after it rejects that promise.
    let promise = run.trace[7]["outcome"]["promise"].clone();
    let settled = run.trace[8]["settled"].as_array().expect("settled");
    let save = settled.iter().find(|s| s["promise"] == promise).expect("snapshot:save settles");
    assert!(save.get("resolved").is_none(), "{save}");
    assert!(save.to_string().contains("the picture could not be encoded"), "{save}");
}
